#!/usr/bin/env python3
# patch-158-E1: multi-asset interactions (attach, detach, add service to asset)
"""
Fifth patch in the multi-asset arc. Makes the multi-asset appointment
view interactive: staff can attach assets, detach them, and add services
or add-ons to each asset card.

What ships:
  - 4 new ops on AppointmentController PATCH endpoint:
    * attach_existing_asset  -> pivots a customer asset onto this appointment
                                + bumps last_seen_at
    * attach_new_asset       -> creates a new customer_asset AND attaches it
    * detach_asset           -> removes the pivot; unpins services to "loose"
                                so they survive on the appointment
    * add_service_to_asset   -> creates an item or addon pinned to a specific
                                asset; recalcs asset subtotal + appointment total

  - Controller now passes pickerAssets (customer's saved assets not yet
    attached to this appointment) to the multi-asset view

  - Multi-asset view gains:
    * Working "+ Attach asset" button with two-tab modal
      (existing customer assets / add new inline)
    * Working "+ Add service or add-on" per asset card with two-tab
      modal (services / add-ons from existing catalog)
    * Working detach button (X) on each asset head
    * Vanilla JS modal handling, fetch-based API calls
    * Reloads page on success so subtotals and "Existing/New" pills
      reflect actual DB state

Out of scope for 158-E1 (deferred to 158-E2):
  - Status pipeline (Confirm / Start / Complete) in the rail
  - Add/remove charges
  - Mark paid / payment actions
  - Per-service remove (have to detach the whole asset for now)
  - Inline price/duration overrides
  - Drag reorder

Manual test:
  1. On a tenant with multi_asset_enabled (bikeshop):
  2. Open any appointment that has no assets yet -> renders legacy view
  3. Use tinker to attach one asset to switch into the multi-asset view
     (or build a fresh appointment after E2 ships the create-flow path)
  4. Click "+ Attach asset" -> modal opens with two tabs
     - Existing tab shows other assets on this customer
     - New tab lets you create + attach inline
  5. Click "+ Add service or add-on" on an asset card -> modal with
     two tabs (services / add-ons), pick one, Add
  6. Click X on an asset head -> confirm dialog -> detach
     Services move to "Unassigned services" card
  7. Verify subtotals + grand total update on each action

Standalone Python. Idempotent.
"""
